import java.io.*;import java.lang.reflect.*;import java.util.*;import org.prairielearn.api.PlatformApiPrecheck.Api;import org.prairielearn.api.PlatformApiPrecheck.Mismatch;
public class PublishedApi {public static void check(Api api)throws Exception {Class<?> a,b;try{a=api.type("alternative.Alternative$A");b=api.type("alternative.Alternative$B");}catch(Mismatch unavailable){throw new IllegalStateException("Teacher placement не адресовано: нужна ручная привязка, ошибка student API не установлена",unavailable);}api.expect(a.getSimpleName().equals("A")&&b.getSimpleName().equals("B")&&!a.isInterface()&&!b.isInterface(),"классы A/B",a+" / "+b);api.expect(b.getSuperclass()==a,"B extends A",b.getSuperclass().toString());Method base;try{base=a.getDeclaredMethod("f");}catch(NoSuchMethodException absent){api.expect(false,"данный A.f()",Arrays.toString(a.getDeclaredMethods()));return;}api.expect(base.getReturnType()==void.class&&!Modifier.isStatic(base.getModifiers())&&!Modifier.isPrivate(base.getModifiers())&&!Modifier.isFinal(base.getModifiers()),"переопределяемый instance void A.f()",base.toString());var original=Arrays.stream(base.getExceptionTypes()).filter(t->!RuntimeException.class.isAssignableFrom(t)&&!Error.class.isAssignableFrom(t)).toList();api.expect(!original.isEmpty()&&original.stream().allMatch(FileNotFoundException.class::isAssignableFrom),"A.f() checked FileNotFoundException",base.toString());Method child;try{child=b.getDeclaredMethod("f");}catch(NoSuchMethodException e){api.expect(false,"B действительно переопределяет f(), а не наследует/перегружает его",Arrays.toString(b.getDeclaredMethods()));return;}api.expect(child.getReturnType()==void.class&&!Modifier.isStatic(child.getModifiers())&&!Modifier.isPrivate(child.getModifiers()),"instance void B.f() override",child.toString());api.expect(Arrays.stream(child.getExceptionTypes()).allMatch(t->RuntimeException.class.isAssignableFrom(t)||Error.class.isAssignableFrom(t)||FileNotFoundException.class.isAssignableFrom(t)),"checked область B.f() не шире FileNotFoundException; unchecked разрешены",child.toString());

}}

